import pytest

from bedrock_protocol import v1001, v2168, v2225

versions = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ServerSettingsResponse{FormID: 300, FormData: []byte(`{"type":"custom_form"}`)}
RESPONSE = bytes.fromhex("ac02167b2274797065223a22637573746f6d5f666f726d227d")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ServerSettingsResponse{FormID: 0, FormData: nil}
EMPTY = bytes.fromhex("0000")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ServerSettingsResponse{FormData: []byte(strings.Repeat("a", 200))}
LONG = bytes.fromhex(
    ""
)

GOLDENS = (
    [
        pytest.param(
            v.ServerSettingsResponsePacket(form_id=300, form_json='{"type":"custom_form"}'),
            RESPONSE,
            id=f"{v.__name__.rpartition('.')[2]}-response",
        )
        for v in versions
    ]
    + [
        pytest.param(v.ServerSettingsResponsePacket(), EMPTY, id=f"{v.__name__.rpartition('.')[2]}-empty-form-json")
        for v in versions
    ]
    + [
        pytest.param(
            v.ServerSettingsResponsePacket(form_json="a" * 200),
            LONG,
            id=f"{v.__name__.rpartition('.')[2]}-two-byte-length-prefix",
        )
        for v in versions
    ]
)


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_settings_response_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_settings_response_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
